tree = {'lessons': 1, 'children': [
    {'lessons': 2, 'children': []},
    {'lessons': 1, 'children': []},
]}

def count_recursive(node):
    if not node['children']:
        return node['lessons']
    return node['lessons'] + sum(count_recursive(child) for child in node['children'])

def count_iterative(root):
    total = 0
    pending = [root]
    while pending:
        node = pending.pop()
        total += node['lessons']
        pending.extend(node['children'])
    return total

print(count_recursive(tree))
print(count_iterative(tree))

